//go:build amd64

package cpu

// CPUID leaves, and the bits within them that say what the processor has. The
// XCR0 masks are the other half of each answer: the register state the
// operating system has agreed to save.
const (
	CPUID_MAX_LEAF     = 0
	CPUID_FEATURES     = 1
	CPUID_EXTENDED     = 7
	CPUID_SUBLEAF_ZERO = 0
	FEATURE_OSXSAVE    = 1 << 27 // leaf 1, ECX
	FEATURE_AVX        = 1 << 28 // leaf 1, ECX
	FEATURE_AVX2       = 1 << 5  // leaf 7, EBX
	FEATURE_AVX512F    = 1 << 16 // leaf 7, EBX
	FEATURE_AVX512BW   = 1 << 30 // leaf 7, EBX
	FEATURE_GFNI       = 1 << 8  // leaf 7, ECX
	XCR0_SSE_AND_YMM   = 0x6
	XCR0_ZMM           = 0xE0

	// HAS_SSE2 is true on every amd64 processor: SSE2 is part of the baseline
	// the architecture is defined by.
	HAS_SSE2 = true
)

// The probes are generated by avo from gen/main.go into cpu_amd64.s; the
// declarations at the end of this file are what Go sees of them, and go vet's
// asmdecl check holds them and the assembly's frames in step.
//
//go:generate go run ./gen/main.go -out cpu_amd64.s -pkg cpu

// HAS_AVX2 says whether 256-bit VEX-encoded kernels may run, HAS_AVX512 whether
// EVEX-encoded ones needing AVX512BW may, and HAS_GFNI whether the VEX-encoded
// GFNI instructions may. Each is resolved once here, at start-up, rather than
// on any path that would use it.
var (
	HAS_AVX2   = _DetectAVX2()
	HAS_AVX512 = _DetectAVX512()
	HAS_GFNI   = _DetectGFNI()
)

// _DetectAVX2 reports whether AVX2 is present and the YMM state is saved.
//
// Revisions:
//   - 2026-09-22 09:12: initial creation, in lib/bitbuffer
//   - 2026-09-24 01:40: moved here
func _DetectAVX2() bool {
	if top, _, _, _ := _CPUID(CPUID_MAX_LEAF, CPUID_SUBLEAF_ZERO); top < CPUID_EXTENDED {
		return false
	}

	_, _, features, _ := _CPUID(CPUID_FEATURES, CPUID_SUBLEAF_ZERO)
	if features&(FEATURE_OSXSAVE|FEATURE_AVX) != FEATURE_OSXSAVE|FEATURE_AVX {
		return false
	}

	// Without this the YMM halves are not saved across a context switch, and
	// using them would corrupt another process's state.
	if state, _ := _XGetBV(); state&XCR0_SSE_AND_YMM != XCR0_SSE_AND_YMM {
		return false
	}

	_, extended, _, _ := _CPUID(CPUID_EXTENDED, CPUID_SUBLEAF_ZERO)

	return extended&FEATURE_AVX2 != 0
}

// _DetectAVX512 reports whether the 512-bit kernels may run. They need
// everything AVX2 needs, the ZMM and opmask state enabled in XCR0, and both
// AVX512F and AVX512BW - byte and word instructions on ZMM are BW.
//
// Revisions:
//   - 2026-09-23 03:58: initial creation, in lib/bitbuffer
//   - 2026-09-24 01:40: moved here
func _DetectAVX512() bool {
	if !HAS_AVX2 {
		return false
	}

	if state, _ := _XGetBV(); state&XCR0_ZMM != XCR0_ZMM {
		return false
	}

	const WANT = FEATURE_AVX512F | FEATURE_AVX512BW

	_, extended, _, _ := _CPUID(CPUID_EXTENDED, CPUID_SUBLEAF_ZERO)

	return extended&WANT == WANT
}

// _DetectGFNI reports whether the VEX-encoded GFNI instructions may run.
//
// It is gated on AVX2 rather than on the GFNI bit alone because the kernels
// use the 256-bit forms, and a processor may report GFNI while supporting only
// the legacy SSE encoding; the YMM state check is needed either way.
//
// Revisions:
//   - 2026-09-23 00:20: initial creation, in tools/simd/macro
//   - 2026-09-24 01:40: moved here
func _DetectGFNI() bool {
	if !HAS_AVX2 {
		return false
	}

	_, _, features, _ := _CPUID(CPUID_EXTENDED, CPUID_SUBLEAF_ZERO)

	return features&FEATURE_GFNI != 0
}

// _CPUID returns the four registers CPUID fills for the given leaf and subleaf.
//
// Revisions:
//   - 2026-09-24 01:40: initial creation
func _CPUID(leaf, sub uint32) (uint32, uint32, uint32, uint32)

// _XGetBV returns the two halves of XCR0.
//
// Revisions:
//   - 2026-09-24 01:40: initial creation
func _XGetBV() (uint32, uint32)
